"""Generate lesson source, teacher notes, workbook and source register. No network."""
from pathlib import Path
import json
ROOT = Path(__file__).resolve().parent
def write(path,text):
    p=ROOT/path
    p.parent.mkdir(parents=True,exist_ok=True)
    p.write_text(text,encoding="utf-8")
def fence(text):
    return chr(96)*3+"text\n"+text+"\n"+chr(96)*3
data=json.loads((ROOT/"content/meta.json").read_text(encoding="utf-8-sig"))
data["sections"]=[json.loads(p.read_text(encoding="utf-8-sig")) for p in sorted((ROOT/"content/sections").glob("s*.json"),key=lambda p:int(p.stem[1:]))]
write("content/lesson.json",json.dumps(data,ensure_ascii=False,indent=2)+"\n")
sections=data["sections"]
assert len(sections)==9 and sum(s["end"]-s["start"] for s in sections)==180
assert sum(s["end"]-s["start"] for s in sections if s["pair"]==1)==90
assert [x["id"] for s in sections for x in s["slides"]]==list(range(1,31))
schedule="\n".join(f'| {s["pair"]} | {s["start"]}–{s["end"]} | {s["title"]} | {s["outcome"]} |' for s in sections)
guide=[
"# Урок 4. Подготовка информации и риски ИИ — Конспект",
"Версия 21.09.2026. Две пары по 90 учебных минут. Перерыв после первой пары; он не входит в 180 минут.",
"Это не текст для 180 минут непрерывного чтения. Учебное время включает объяснение, чтение исходников, демонстрации, сравнение результатов и самостоятельный выбор слушателя. Ниже есть содержание для озвучки и точные действия на экране.",
"## До занятия",
"Откройте страницу урока, три новых чата GigaChat, DeepSeek и ChatGPT, источники кейсов и ролик Framestore. Проверьте доступ и вход заранее на устройстве лектора. Не меняйте настройки чужих аккаунтов. Очистите экран от рабочих уведомлений. Используйте только вложенные синтетические примеры.",
"Основные живые сравнения трёх моделей: 26–39 минуты — письмо о бюджете; в блоке 90–115 — права на материал; в блоке 115–135 — проверка утверждений. Отправляйте одинаковый текст в три окна последовательно, затем сравнивайте по рубрике. Остальные упражнения работают на странице и на маркированных учебных эталонах; одинаковые промпты оставлены для повторения. Это не результаты реальных испытаний моделей.",
"Если сервис недоступен или ответ не готов, через 60–90 секунд переходите к учебному эталону и явно называйте его заготовкой преподавателя. Не ждите все три сервиса несколько минут и не выдавайте эталон за их ответ. Наблюдения записывайте вручную: модель и дата, версия если видна, выполнение требований, ошибка, правка человека.",
"Если аудитория молчит: предложите бинарный выбор про себя, дайте 5–10 секунд, затем самостоятельно разберите один вариант. Не расходуйте отведённое практике время на ожидание ответа в чате.",
"## Сетка занятия",
"| Пара | Минуты занятия | Блок | Проверяемый результат |\n|---|---:|---|---|\n"+schedule,
"Повторение занимает первые 45 минут. На отметке 90 — перерыв. Вторая пара начинается с авторского права и заканчивается на отметке 180. В каждом блоке указан внутренний сценарий."
]
narration=["Урок четвёртый. Подготовка информации для работы с искусственным интеллектом. Правовые и репутационные риски.","Две пары по девяносто минут. Перерыв после первой пары. Этот текст служит для подготовки преподавателя. Во время занятия объяснения чередуются с демонстрациями и упражнениями."]
workbook=["# Рабочая тетрадь. Урок 4","Все ситуации и входные записи, кроме отдельно обозначенных открытых кейсов, синтетические. Не подставляйте реальные корпоративные данные. Заполняйте локально. Работа самостоятельная, преподавателю на проверку не отправляется.","## Как сравнивать три модели","Откройте новые диалоги GigaChat, DeepSeek и ChatGPT. Скопируйте одинаковые промпт и учебные данные. Сравните ответ с эталоном, а не только с ответами других моделей. Если модель не доступна, отметьте это; не заменяйте наблюдение догадкой.","| Модель и дата | Требования выполнены | Что неверно/неизвестно | Правка человека |\n|---|---|---|---|\n| GigaChat | | | |\n| DeepSeek | | | |\n| ChatGPT | | | |"]
for s in sections:
    label=f'Пара {s["pair"]}. {s["start"]}–{s["end"]} мин. {s["title"]}'
    guide+=["## "+label,"**Результат:** "+s["outcome"],"**Внутренний тайминг:** "+s["teacher"]["pace"],"### Пояснение",s["teacher"]["speech"],"### Развернутое объяснение"]
    narration+=[label,s["teacher"]["speech"]]
    for term in s.get("terms",[]):
        guide+=[f'**{term["term"]}.** {term["text"]}']
        narration+=[f'{term["term"]}. {term["text"]}']
    guide+=s["paragraphs"]
    narration+=s["paragraphs"]
    for slide in s["slides"]:
        guide+=[f'### Слайд {slide["id"]:03d}. {slide["title"]}',slide["explanation"],"**Покажите на примере:** "+slide["example"],"**Скажите в завершение:** "+slide["takeaway"]]
        narration+=[f'Слайд {slide["id"]}. {slide["title"]}.',slide["explanation"],"Пример. "+slide["example"],"Главный вывод. "+slide["takeaway"]]
    case=s.get("case")
    if case:
        guide+=["### Открытый кейс и источник",case["text"],f'[{case["label"]}]({case["url"]})',*[f'{i+1}. {v}' for i,v in enumerate(case["steps"])],"**Граница вывода:** "+case["caution"]]
        narration+=["Разберём подтверждённый открытый пример.",case["text"],*case["steps"],case["caution"]]
    table=s.get("worked_table")
    if table:
        lines=[" | ".join(row) for row in table["rows"]]
        guide += ["### "+table["title"],*lines]
        narration += [table["title"],*lines]
        workbook += ["### "+table["title"],*lines]
    for t in s.get("prompt_templates",[]):
        guide += ["### "+t["title"],fence(t["prompt"]),t["example"],t["check"]]
        workbook += ["### "+t["title"],fence(t["prompt"]),t["example"],t["check"]]
        narration += [t["title"],t["example"],t["check"]]
    p=s["practice"]
    guide+=[f'### Практика — {p["minutes"]} минут внутри блока. {p["title"]}',"Прочитайте задачу слушателям. Покажите вход до вызова модели. Попросите назвать ожидаемый результат, затем показывайте действия.",fence(p["input"]),"#### Единый промпт для трёх моделей",fence(p["prompt"]),"#### Действия на экране",*[f'{i+1}. {v}' for i,v in enumerate(p["steps"])],"#### Как проверить результат",*["- "+x for x in p["expected"]],"#### Резерв при недоступности сервисов",p["fallback"],"#### Если никто не отвечает",s["teacher"]["silent"]]
    narration+=["Практика. "+p["title"],p["input"],"Задание модели.",p["prompt"],"Порядок разбора.",*p["steps"],"Ожидаемый результат.",*p["expected"],"Если сервис недоступен.",p["fallback"],"Если никто не отвечает.",s["teacher"]["silent"]]
    if s.get("interactive"):
        x=s["interactive"]
        guide+=["### Как показать интерактив",x["instruction"],*[f'{i+1}. {v}' for i,v in enumerate(x["steps"])],"**Итог:** "+x["result"],"После разбора нажмите «Сбросить», предложите другой выбор и сравните объяснение. Это локальная учебная модель, не проверка настоящих документов."]
        narration+=["Интерактив на странице.",x["instruction"],*x["steps"],x["result"]]
    guide+=["### Источники блока",*[f'- [{x["title"]}]({x["url"]})' for x in s["sources"]]]
    workbook+=["## "+p["title"],fence(p["input"]),"### Запрос",fence(p["prompt"]),"### Выполните",*[f'{i+1}. {v}' for i,v in enumerate(p["steps"])],"### Запишите свой результат","Мой ответ: ___________________\n\nОснования и источник: ___________________\n\nЧто неизвестно и что уточнить: ___________________","### Самопроверка",*["- "+x for x in p["expected"]],p["fallback"]]
    if s["id"]=="s4":
        guide+=["# ПЕРЕРЫВ — ПЕРВАЯ ПАРА ЗАВЕРШЕНА","90 учебных минут пройдены. После перерыва откройте блок «Авторское право». Начинается вторая пара на 90 минут."]
        narration+=["Первая пара завершена. Перерыв. После перерыва начинается вторая пара — правовые и репутационные риски."]
guide+=["## Что полезно, что проверить, что не применять без специалиста","Полезно: пустые шаблоны, минимальные синтетические наборы, выделение утверждений, чек-листы проверки. Проверить: арифметику, происхождение, условия использования, фактическую конфигурацию среды. Без профильного специалиста не принимайте спорные правовые решения, не согласовывайте передачу закрытых данных, не делайте кадровые выводы по генерации и не выдавайте проверку записи за экспертизу.","## Самостоятельная работа","Участники завершают те же бланки и повторяют один пример на доступной модели. Новое задание не добавляется. Проверка преподавателем не предусмотрена, эталоны есть в рабочей тетради.","## Границы достоверности","Кейсы основаны на указанных источниках; примеры ответов — учебные заготовки. Здесь нет результатов реального сравнительного теста трёх сервисов. Юридический блок объясняет общие принципы, не заменяет правовую оценку конкретного случая. Ролики не скачивались; доступность видео из сети организации требует проверки до занятия."]
write("teacher-guide.md","\n\n".join(guide)+"\n")
write("downloads/teacher-narration.txt","\n\n".join(narration)+"\n")
write("downloads/lesson4-student-workbook.md","\n\n".join(workbook)+"\n")
sources=["# Карта источников","Проверка 21.09.2026. Открытые страницы и официальные материалы. Содержание пересказано для учебного разбора; нет закрытых документов организации.","| Блок | Источник | Для чего используется |\n|---|---|---|"]
for s in sections:
    for src in s["sources"]:
        sources.append(f'| {s["id"]}: {s["title"]} | [{src["title"]}]({src["url"]}) | Определения, условия или проверка кейса блока |')
sources+=["","## Границы переносимости","Российские правовые принципы — ГК РФ; позиции США и определения ЕС обозначены как зарубежные. Mata — текст судебного акта на правовой платформе Justia. EEOC — урегулирование автоматизированного отбора, не исследование конкретной LLM. Framestore — синтетическая замена лица, голос актрисы сохранён. HK$200 млн — предварительно записанная конференция без взаимодействия. Подробные оговорки есть непосредственно в блоках.","## Проверка на занятии","Откройте страницу первоисточника, найдите нужный фрагмент и сравните с утверждением. Если источник недоступен, используйте подготовленный пересказ с пометкой и не заявляйте, что выполнили текущую онлайн-проверку."]
write("downloads/lesson4-source-map.md","\n\n".join(sources)+"\n")
write("Docs/lesson-plan.md","# План и критерии урока\n\nДве пары 90 + 90 минут, перерыв между ними. Первые 45 минут — повторение.\n\n| Пара | Минуты | Блок | Результат |\n|---|---:|---|---|\n"+schedule+"\n\nПриёмка: 30 слайдов с пояснениями; 9 практик; одинаковые запросы для трёх моделей; 3 основных живых сравнения; определения; первоисточники; резерв при молчании и недоступности сервиса; отдельный конспект. Обзор анонимизаторов НЕ входит в публикацию.\n")
try:
    from docx import Document
    doc=Document()
    for block in guide:
        for line in block.splitlines():
            if line.startswith("#"):
                level=min(len(line)-len(line.lstrip("#")),3)
                doc.add_heading(line.lstrip("# ").replace("**",""),level=level)
            elif line and not line.startswith(chr(96)*3):
                doc.add_paragraph(line.replace("**",""))
    doc.save(ROOT/"downloads/teacher-guide.docx")
except ImportError:
    print("python-docx not found: Markdown and TXT created")
print("Reviewed sections:",len(sections),"Teaching minutes:",180,"Narration words:",len(" ".join(narration).split()))
